From 559738e3535c1d999c4cf5c2426968cf3dfd4f8b Mon Sep 17 00:00:00 2001
From: Benjamin Fleischer <fleiben@gmail.com>
Date: Wed, 20 Sep 2017 22:02:30 +0200
Subject: [PATCH] Fix statfs_x bug when using modules

This fixes a bug introduced in commit ba5744c. We need to track whether
the actual file system implements the high-level statfs_x callback or
not. Checking if f->op.statfs_x exists is not sufficient in case
modules are used.

diff --git a/lib/fuse.c b/lib/fuse.c
index a015467..5b0b1d8 100644
--- a/lib/fuse.c
+++ b/lib/fuse.c
@@ -163,6 +163,9 @@ struct fuse {
 	struct fuse_fs *fs;
 	int nullpath_ok;
 	int utime_omit_ok;
+#ifdef __APPLE__
+	int statfs_x_ok;
+#endif
 	struct lock_queue_element *lockq;
 	int pagesize;
 	struct list_head partial_slabs;
@@ -4078,10 +4081,10 @@ static void fuse_lib_statfs(fuse_req_t req, fuse_ino_t ino)
 		struct fuse_intr_data d;
 		fuse_prepare_interrupt(f, req, &d);
 #ifdef __APPLE__
-                if (f->fs->op.statfs_x)
+		if (f->statfs_x_ok)
 			err = fuse_fs_statfs_x(f->fs, path ? path : "/",
 					       &buf.statfs);
-                else
+		else
 #endif
 			err = fuse_fs_statfs(f->fs, path ? path : "/",
 					     &buf.statvfs);
@@ -4091,7 +4094,7 @@ static void fuse_lib_statfs(fuse_req_t req, fuse_ino_t ino)

 	if (!err)
 #ifdef __APPLE__
-                if (f->fs->op.statfs_x)
+                if (f->statfs_x_ok)
 			fuse_reply_statfs_x(req, &buf.statfs);
                 else
 #endif
@@ -5086,6 +5089,9 @@ static int fuse_push_module(struct fuse *f, const char *module,
 	f->nullpath_ok = newfs->op.flag_nullpath_ok && f->nullpath_ok;
 	f->conf.nopath = newfs->op.flag_nopath && f->conf.nopath;
 	f->utime_omit_ok = newfs->op.flag_utime_omit_ok && f->utime_omit_ok;
+#ifdef __APPLE__
+	f->statfs_x_ok = newfs->op.statfs_x != NULL && f->statfs_x_ok;
+#endif
 	return 0;
 }

@@ -5185,6 +5191,9 @@ struct fuse *fuse_new_common(struct fuse_chan *ch, struct fuse_args *args,
 	f->nullpath_ok = fs->op.flag_nullpath_ok;
 	f->conf.nopath = fs->op.flag_nopath;
 	f->utime_omit_ok = fs->op.flag_utime_omit_ok;
+#ifdef __APPLE__
+	f->statfs_x_ok = fs->op.statfs_x != NULL;
+#endif

 	/* Oh f**k, this is ugly! */
 	if (!fs->op.lock) {
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by an insufficient check for the existence of the `statfs_x` callback in filesystems that use modules. The original implementation only checked if `f->fs->op.statfs_x` existed, which was not reliable in cases where modules were involved. This led to incorrect behavior when determining whether to use the `statfs_x` or `statfs` function, resulting in potential failures or incorrect responses.

        Commit message:
        Fix statfs_x bug when using modules

This fixes a bug introduced in commit ba5744c. We need to track whether
the actual file system implements the high-level statfs_x callback or
not. Checking if f->op.statfs_x exists is not sufficient in case
modules are used.  

        Patch:
         	int nullpath_ok;
 	int utime_omit_ok;
+#ifdef __APPLE__
+	int statfs_x_ok;
+#endif
 	struct lock_queue_element *lockq;
 	int pagesize;

 static void fuse_lib_statfs(fuse_req_t req, fuse_ino_t ino)
 {
 	struct fuse *f = req_fuse_prepare(req);
 	union {
 		struct statvfs statvfs;
 #ifdef __APPLE__
 		struct statfs statfs;
 #endif
 	} buf;
 	char *path = NULL;
 	int err = 0;

 	memset(&buf, 0, sizeof(buf));
 	if (ino)
 		err = get_path(f, ino, &path);

 	if (!err) {
 		struct fuse_intr_data d;
 		fuse_prepare_interrupt(f, req, &d);
 #ifdef __APPLE__
-                if (f->fs->op.statfs_x)
+		if (f->statfs_x_ok)
 			err = fuse_fs_statfs_x(f->fs, path ? path : "/",
 					       &buf.statfs);
-                else
+		else
 #endif
 			err = fuse_fs_statfs(f->fs, path ? path : "/",
 					     &buf.statvfs);
 		fuse_finish_interrupt(f, req, &d);
 		free_path(f, ino, path);
 	}

 	if (!err)
 #ifdef __APPLE__
-                if (f->fs->op.statfs_x)
+                if (f->statfs_x_ok)
 			fuse_reply_statfs_x(req, &buf.statfs);
                 else
 #endif
 			fuse_reply_statfs(req, &buf.statvfs);
 	else
 		reply_err(req, err);
 }


 static int fuse_push_module(struct fuse *f, const char *module,
 			    struct fuse_args *args)
 {
 	struct fuse_fs *fs[2] = { f->fs, NULL };
 	struct fuse_fs *newfs;
 	struct fuse_module *m = fuse_get_module(module);

 	if (!m)
 		return -1;

 	newfs = m->factory(args, fs);
 	if (!newfs) {
 		fuse_put_module(m);
 		return -1;
 	}
 	newfs->m = m;
 	f->fs = newfs;
 	f->nullpath_ok = newfs->op.flag_nullpath_ok && f->nullpath_ok;
 	f->conf.nopath = newfs->op.flag_nopath && f->conf.nopath;
 	f->utime_omit_ok = newfs->op.flag_utime_omit_ok && f->utime_omit_ok;
+#ifdef __APPLE__
+	f->statfs_x_ok = newfs->op.statfs_x != NULL && f->statfs_x_ok;
+#endif
 	return 0;
 }


 struct fuse *fuse_new_common(struct fuse_chan *ch, struct fuse_args *args,
 			     const struct fuse_operations *op,
 			     size_t op_size, void *user_data, int compat)
 {
 	struct fuse *f;
 	struct node *root;
 	struct fuse_fs *fs;
 	struct fuse_lowlevel_ops llop = fuse_path_ops;

 	if (fuse_create_context_key() == -1)
 		goto out;

 	f = (struct fuse *) calloc(1, sizeof(struct fuse));
 	if (f == NULL) {
 		fprintf(stderr, "fuse: failed to allocate fuse object\n");
 		goto out_delete_context_key;
 	}

 	fs = fuse_fs_new(op, op_size, user_data);
 	if (!fs)
 		goto out_free;

 	fs->compat = compat;
 	f->fs = fs;
 	f->nullpath_ok = fs->op.flag_nullpath_ok;
 	f->conf.nopath = fs->op.flag_nopath;
 	f->utime_omit_ok = fs->op.flag_utime_omit_ok;
+#ifdef __APPLE__
+	f->statfs_x_ok = fs->op.statfs_x != NULL;
+#endif

 	/* Oh f**k, this is ugly! */
 	if (!fs->op.lock) {
 		llop.getlk = NULL;
 		llop.setlk = NULL;
 	}

 	f->conf.entry_timeout = 1.0;
 	f->conf.attr_timeout = 1.0;
 	f->conf.negative_timeout = 0.0;
 	f->conf.intr_signal = FUSE_DEFAULT_INTR_SIGNAL;

 #ifdef __APPLE__
 	f->pagesize = sysconf(_SC_PAGESIZE);
 #else
 	f->pagesize = getpagesize();
 #endif
 	init_list_head(&f->partial_slabs);
 	init_list_head(&f->full_slabs);
 	init_list_head(&f->lru_table);

 	if (fuse_opt_parse(args, &f->conf, fuse_lib_opts,
 			   fuse_lib_opt_proc) == -1)
 		goto out_free_fs;

 #ifdef __APPLE__
 	if (!f->conf.iconpath) {
 		char *iconpath = fuse_resource_path(OSXFUSE_VOLUME_ICON);
 		struct stat stbuf;

 		if (stat(iconpath, &stbuf) == 0) {
 			char *modules;
 			size_t modules_len = 0;
 			char *modules_ptr;

 			if (f->conf.modules)
 				modules_len = strlen(f->conf.modules);

 			modules = (char *)malloc(modules_len +
 						 sizeof(":volicon"));
 			if (!modules) {
 				free(iconpath);
 				fprintf(stderr, "fuse: failed to allocate modules string\n");
 				goto out_free_fs;
 			}

 			modules_ptr = modules;
 			if (modules_len) {
 				modules_ptr = stpcpy(modules_ptr,
 						     f->conf.modules);
 				*modules_ptr = ':';
 				modules_ptr++;
 			}
 			modules_ptr = stpcpy(modules_ptr, "volicon");
 			*modules_ptr = '\0';

 			free(f->conf.modules);
 			f->conf.modules = modules;
 			f->conf.iconpath = iconpath;
 		}
 	}

 	if (f->conf.iconpath) {
 		char iconpath_arg[MAXPATHLEN + 12];

 		if (snprintf(iconpath_arg, sizeof(iconpath_arg),
 			     "-oiconpath=%s", f->conf.iconpath) <= 0) {
 			fprintf(stderr, "fuse: failed to create iconpath argument\n");
 			goto out_free_fs;
 		}
 		if (fuse_opt_add_arg(args, iconpath_arg) == -1) {
 			fprintf(stderr, "fuse: failed to add iconpath argument\n");
 			goto out_free_fs;
 		}
 	}
 #endif /* __APPLE__ */

 	if (f->conf.modules) {
 		char *module;
 		char *next;

 		for (module = f->conf.modules; module; module = next) {
 			char *p;
 			for (p = module; *p && *p != ':'; p++);
 			next = *p ? p + 1 : NULL;
 			*p = '\0';
 			if (module[0] &&
 			    fuse_push_module(f, module, args) == -1)
 				goto out_free_fs;
 		}
 	}

 	if (!f->conf.ac_attr_timeout_set)
 		f->conf.ac_attr_timeout = f->conf.attr_timeout;

 #if defined(__FreeBSD__) || defined(__NetBSD__) || defined(__APPLE__)
 	/*
 	 * In FreeBSD, we always use these settings as inode numbers
 	 * are needed to make getcwd(3) work.
 	 */
 	f->conf.readdir_ino = 1;
 #endif

 	if (compat && compat <= 25) {
 		if (fuse_sync_compat_args(args) == -1)
 			goto out_free_fs;
 	}

 	f->se = fuse_lowlevel_new_common(args, &llop, sizeof(llop), f);
 	if (f->se == NULL) {
 		if (f->conf.help)
 			fuse_lib_help_modules();
 		goto out_free_fs;
 	}

 	fuse_session_add_chan(f->se, ch);

 	if (f->conf.debug) {
 		fprintf(stderr, "nullpath_ok: %i\n", f->nullpath_ok);
 		fprintf(stderr, "nopath: %i\n", f->conf.nopath);
 		fprintf(stderr, "utime_omit_ok: %i\n", f->utime_omit_ok);
 	}

 	/* Trace topmost layer by default */
 	f->fs->debug = f->conf.debug;
 	f->ctr = 0;
 	f->generation = 0;
 	if (node_table_init(&f->name_table) == -1)
 		goto out_free_session;

 	if (node_table_init(&f->id_table) == -1)
 		goto out_free_name_table;

 	fuse_mutex_init(&f->lock);

 	root = alloc_node(f);
 	if (root == NULL) {
 		fprintf(stderr, "fuse: memory allocation failed\n");
 		goto out_free_id_table;
 	}
 	if (lru_enabled(f)) {
 		struct node_lru *lnode = node_lru(root);
 		init_list_head(&lnode->lru);
 	}

 	strcpy(root->inline_name, "/");
 	root->name = root->inline_name;

 	if (f->conf.intr &&
 	    fuse_init_intr_signal(f->conf.intr_signal,
 				  &f->intr_installed) == -1)
 		goto out_free_root;

 	root->parent = NULL;
 	root->nodeid = FUSE_ROOT_ID;
 	inc_nlookup(root);
 	hash_id(f, root);

 #ifdef __APPLE__
 	f->fs->fuse = f;
 	fuse_set_fuse_internal_np(fuse_chan_fd(ch), f);
 #endif

 	return f;

 out_free_root:
 	free(root);
 out_free_id_table:
 	free(f->id_table.array);
 out_free_name_table:
 	free(f->name_table.array);
 out_free_session:
 	fuse_session_destroy(f->se);
 out_free_fs:
 	/* Horrible compatibility hack to stop the destructor from being
 	   called on the filesystem without init being called first */
 	fs->op.destroy = NULL;
 	fuse_fs_destroy(f->fs);
 	free(f->conf.modules);
 #ifdef __APPLE__
 	free(f->conf.iconpath);
 #endif
 out_free:
 	free(f);
 out_delete_context_key:
 	fuse_delete_context_key();
 out:
 	return NULL;
 }



